CREATE TABLE IF NOT EXISTS customer_messaging_preferences (id TEXT PRIMARY KEY, restaurant_id TEXT NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, phone TEXT NOT NULL, consent TEXT NOT NULL DEFAULT 'UNKNOWN' CHECK(consent IN ('UNKNOWN','OPTED_IN','OPTED_OUT')), language TEXT NOT NULL DEFAULT 'EN' CHECK(language IN ('EN','ES')), updated_at TEXT NOT NULL, UNIQUE(restaurant_id,phone));
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, restaurant_id TEXT NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, channel TEXT NOT NULL CHECK(channel='SMS'), event_type TEXT NOT NULL, recipient_type TEXT NOT NULL, recipient_id TEXT, recipient_phone TEXT NOT NULL, template_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'QUEUED' CHECK(status IN ('QUEUED','SENDING','SENT','FAILED','SUPPRESSED')), idempotency_key TEXT NOT NULL, message_id TEXT, metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, sent_at TEXT, failed_at TEXT, UNIQUE(restaurant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, restaurant_id TEXT NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, notification_id TEXT REFERENCES notifications(id), provider TEXT NOT NULL, provider_message_id TEXT, channel TEXT NOT NULL CHECK(channel='SMS'), direction TEXT NOT NULL CHECK(direction IN ('OUTBOUND','INBOUND')), to_phone TEXT NOT NULL, from_phone TEXT, template_key TEXT, status TEXT NOT NULL CHECK(status IN ('QUEUED','SENDING','SENT','DELIVERED','FAILED','UNDELIVERED','CANCELLED','UNKNOWN')), body TEXT NOT NULL, provider_status TEXT, provider_error_code TEXT, provider_error_message TEXT, metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, sent_at TEXT, delivered_at TEXT, failed_at TEXT);
CREATE TABLE IF NOT EXISTS outbox_events (id TEXT PRIMARY KEY, restaurant_id TEXT NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, event_type TEXT NOT NULL, aggregate_type TEXT NOT NULL, aggregate_id TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', attempts INTEGER NOT NULL DEFAULT 0, available_at TEXT NOT NULL, processed_at TEXT, created_at TEXT NOT NULL, UNIQUE(restaurant_id,event_type,aggregate_type,aggregate_id));
CREATE INDEX IF NOT EXISTS idx_notifications_tenant_created ON notifications(restaurant_id,created_at); CREATE INDEX IF NOT EXISTS idx_messages_provider ON messages(provider_message_id); CREATE INDEX IF NOT EXISTS idx_outbox_status ON outbox_events(status,available_at);
